def palindrom(teks):
    b = "".join(c.lower() for c in teks if c.isalnum())
    return b == b[::-1]

def frekuensi_kata(teks):
    hasil = {}
    for k in teks.split():
        k = k.strip(".,!?;:").lower()
        if k:
            hasil[k] = hasil.get(k, 0) + 1
    return hasil

