exercises.solution:
def persen(bagian, total):
    if total == 0:
        return "n/a"
    return f"{bagian / total:.1%}"

def tabel(baris):
    if not baris:
        return ""
    lebar = max(len(n) for n, _ in baris)
    return "\n".join(f"{n:<{lebar}} {v:>8.2f}" for n, v in baris)

import re

def ambil_angka(teks):
    return [int(x) for x in re.findall(r"\d+", teks)]

import re

def rapikan_spasi(teks):
    return re.sub(r"\s+", " ", teks).strip()

import re

def valid_plat(teks):
    return bool(re.fullmatch(r"[A-Z]{1,2} \d{1,4} [A-Z]{1,3}", teks))
